"""Value-matched renderer paths for a subsequent, separately locked experiment.

This module is tested scaffolding; it has not been used to train a model.
"""
import torch

from common import render


def rendered_training_output(function, raw, features, route):
    if route == "joint":
        return function(raw, features, render=True, warmup=1.)["rendered"]
    if route == "stop_head_parameters":
        # Preserve both direct and indirect backbone/input gradients. Detaching
        # the rendered geometry itself would not implement this comparison.
        parameters = {name: parameter.detach() for name, parameter in function.named_parameters()}
        return torch.func.functional_call(function, parameters, (raw, features),
            dict(render=True, warmup=1.))["rendered"]
    if route == "direct_voxel_only":
        out = function(raw, features, render=False, warmup=1.)
        return render(raw, out["lower"].detach(), out["upper"].detach(),
                      out["log_pres"].detach(), out["beta"].detach())
    raise ValueError(route)

