"""Keep historical transforms from modifying source arrays through tensor views."""
import copy
import hashlib
import numpy as np
import torch

class CopyBeforeTransform:
    def __init__(self,transform): self.transform=transform
    def __call__(self,row): return self.transform(copy.deepcopy(row))

def source_digest(dataset):
    h=hashlib.sha256()
    for row in dataset.data:
        for key in ('image','label'):
            x=np.asarray(row[key]);h.update(str((x.shape,x.dtype)).encode());h.update(x.tobytes())
    return h.hexdigest()

def protect_and_audit(loader):
    ds=loader.dataset;before=source_digest(ds)
    # Prove the legacy transform's behavior on a disposable copy, never ds.data.
    probe=copy.deepcopy(ds.data[0]);original=copy.deepcopy(probe)
    ds.transform(probe)
    legacy_mutates=not np.array_equal(probe['image'],original['image'])
    ds.transform=CopyBeforeTransform(ds.transform)
    repeat=True
    for i in range(len(ds)):
        a=ds[i];b=ds[i]
        repeat=repeat and torch.equal(a['image'],b['image']) and torch.equal(a['label'],b['label'])
    unchanged=source_digest(ds)==before
    assert repeat and unchanged, 'Input preprocessing is not stable'
    return dict(cases=len(ds),legacy_mutates_disposable_source=legacy_mutates,
                all_repeated_inputs_exact=repeat,source_arrays_unchanged=unchanged),before

"""Annotated union contour supervision directly on raw three-class probabilities."""
import hashlib
import numpy as np
import torch
from scipy.ndimage import distance_transform_edt

def signed_distance(foreground):
    """Signed EDT to opposite-label voxel centers, with 1mm grid spacing.

    Negative on every foreground voxel, positive on every background voxel.
    This discrete convention has +/-1 at nearest opposing voxel centers; it is
    not an exact subvoxel surface distance and does not zero thin foreground.
    """
    fg=np.asarray(foreground,dtype=bool)
    if fg.ndim!=3 or not fg.any() or fg.all():
        raise ValueError('Signed EDT requires nonempty foreground and background in a 3D target')
    return (distance_transform_edt(~fg)-distance_transform_edt(fg)).astype(np.float32)

class DistanceCache:
    """RAM-only target cache; no subject metadata or distance maps are exported."""
    def __init__(self): self.cache={}
    def __call__(self,labels):
        labels=labels.detach()
        masks=(labels[:,0] if labels.ndim==5 else labels).cpu().numpy()>0
        fields=[]
        for m in masks:
            key=(m.shape,hashlib.sha256(m.tobytes()).hexdigest())
            if key not in self.cache: self.cache[key]=signed_distance(m)
            fields.append(self.cache[key])
        return torch.as_tensor(np.stack(fields),device=labels.device)

def boundary_loss(raw,field):
    if raw.ndim!=5 or raw.shape[1]!=3 or raw.shape[0:1]+raw.shape[2:]!=field.shape:
        raise ValueError('Expected Bx3xXxYxZ logits and BxXxYxZ target distances')
    p=raw.float().softmax(1)[:,1:].sum(1)
    return (p*field.detach().float()).mean()

def combined(base,raw,field,coefficient):
    boundary=boundary_loss(raw,field)
    return base+coefficient*boundary,boundary

