#!/usr/bin/env python3
"""Measure proposed semantic constraints on MSD labels and saved predictions.

The script fits learned priors on fold-0 training labels only. Five-fold
cross-fitting supplies unbiased training-label scores for the atlas and PCA
shape constraints. Validation labels and saved model outputs are never used to
fit a prior or an adherence threshold.
"""

from __future__ import annotations

import argparse
import csv
import json
import math
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd
from scipy import ndimage


EPS = 1e-8
SPATIAL_SIZE = (64, 64, 64)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pkl", type=Path, required=True)
    parser.add_argument("--splits-json", type=Path, required=True)
    parser.add_argument("--fold", type=int, default=0)
    parser.add_argument("--prediction-index", type=Path, required=True)
    parser.add_argument("--prediction-dir", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--pca-components", type=int, default=16)
    parser.add_argument("--pca-size", type=int, default=16)
    parser.add_argument("--calibration-quantile", type=float, default=0.99)
    return parser.parse_args()


def center_pad_crop(array: np.ndarray, size: tuple[int, int, int] = SPATIAL_SIZE) -> np.ndarray:
    result = np.asarray(array)
    pads: list[tuple[int, int]] = []
    for current, target in zip(result.shape, size):
        missing = max(target - current, 0)
        pads.append((missing // 2, missing - missing // 2))
    result = np.pad(result, pads, mode="constant")
    slices = []
    for current, target in zip(result.shape, size):
        start = max((current - target) // 2, 0)
        slices.append(slice(start, start + target))
    return result[tuple(slices)]


def normalize_image(image: np.ndarray) -> np.ndarray:
    image = np.asarray(image, dtype=np.float32)
    nonzero = image != 0
    if nonzero.any():
        values = image[nonzero]
        image = image.copy()
        image[nonzero] = (values - values.mean()) / max(float(values.std()), EPS)
    return center_pad_crop(image).astype(np.float32)


def one_hot(labels: np.ndarray) -> np.ndarray:
    return np.stack([(labels == class_id).astype(np.float32) for class_id in range(3)])


def dice_per_case(gt: np.ndarray, pred: np.ndarray) -> float:
    scores = []
    for class_id in (1, 2):
        a = gt == class_id
        b = pred == class_id
        scores.append(float(2 * np.logical_and(a, b).sum() / max(a.sum() + b.sum(), EPS)))
    return float(np.mean(scores))


def make_folds(n: int, count: int = 5, seed: int = 42) -> list[np.ndarray]:
    indices = np.arange(n)
    np.random.default_rng(seed).shuffle(indices)
    return [np.asarray(part, dtype=int) for part in np.array_split(indices, count)]


def build_atlas(probabilities: np.ndarray) -> np.ndarray:
    atlas = probabilities.mean(axis=0, dtype=np.float64)
    for class_id in (1, 2):
        atlas[class_id] = ndimage.gaussian_filter(atlas[class_id], sigma=0.75)
    atlas = np.maximum(atlas, 1e-6)
    atlas /= atlas.sum(axis=0, keepdims=True)
    return atlas.astype(np.float32)


def normalized_spatial_distribution(mask: np.ndarray) -> np.ndarray:
    flat = np.asarray(mask, dtype=np.float64).ravel()
    flat = np.maximum(flat, 0.0) + 1e-12
    return flat / flat.sum()


def js_divergence(p: np.ndarray, q: np.ndarray) -> float:
    p = normalized_spatial_distribution(p)
    q = normalized_spatial_distribution(q)
    midpoint = 0.5 * (p + q)
    return float(
        0.5 * np.sum(p * np.log(p / midpoint))
        + 0.5 * np.sum(q * np.log(q / midpoint))
    )


def atlas_energy(probabilities: np.ndarray, atlas: np.ndarray) -> float:
    return float(
        np.mean(
            [
                js_divergence(probabilities[class_id], atlas[class_id])
                for class_id in (1, 2)
            ]

