"""Preserve all non-weight files before the explicitly approved 50-epoch cleanup."""
import hashlib
import io
import json
import tarfile
from datetime import datetime, timezone
from pathlib import Path

HOME = Path('/mnt/beegfsstudents/home/3160552')
ROOT = HOME / 'low_data_noaug_fold1_20260917_01'
DEST = ROOT / 'retired_50epoch_results'

def sha(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        for block in iter(lambda: f.read(8 * 1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()

def main():
    proposal = json.loads((ROOT / 'STORAGE_PROPOSAL.json').read_text())
    roots = sorted({Path(e['run']).parent.parent for e in proposal['experiments']})
    files, excluded = [], []
    for root in roots:
        for p in sorted(root.rglob('*')):
            if p.is_symlink():
                raise RuntimeError(f'Inspect symlink before archiving: {p}')
            if not p.is_file():
                continue
            entry = {'path': str(p), 'relative_path': str(p.relative_to(HOME)), 'bytes': p.stat().st_size}
            if p.suffix.lower() in {'.pt', '.pth', '.ckpt', '.pyc'}:
                entry['reason'] = 'Model weights remain subject to explicit deletion list; bytecode is reproducible'
                excluded.append(entry)
            else:
                files.append(entry)
    size = sum(x['bytes'] for x in files)
    print(json.dumps({'file_count': len(files), 'bytes': size, 'largest': sorted(files, key=lambda x: x['bytes'], reverse=True)[:8]}), flush=True)
    assert size < 300 * 1024**2, 'Inspect unexpectedly large results before archiving'
    for e in proposal['experiments']:
        complete = json.loads((Path(e['run']) / 'completion_manifest.json').read_text())
        assert complete['status'] == 'complete'
    DEST.mkdir(exist_ok=True)
    assert not (DEST / 'results.tar.gz').exists()
    for item in files:
        item['sha256'] = sha(Path(item['path']))
    manifest = {'created_utc': datetime.now(timezone.utc).isoformat(), 'authorization': 'User: yes but save the results',
                'files': files, 'excluded': excluded, 'approved_weight_deletion_proposal': proposal}
    manifest_bytes = (json.dumps(manifest, indent=2) + '\n').encode()
    (DEST / 'RESULTS_MANIFEST.json').write_bytes(manifest_bytes)
    with tarfile.open(DEST / 'results.tar.gz', 'w:gz') as archive:
        info = tarfile.TarInfo('RESULTS_MANIFEST.json')
        info.size = len(manifest_bytes)
        archive.addfile(info, io.BytesIO(manifest_bytes))
        for item in files:
            archive.add(item['path'], arcname=item['relative_path'], recursive=False)
    for item in files:
        assert sha(Path(item['path'])) == item['sha256'], item['path']
    result = {'archive_sha256': sha(DEST / 'results.tar.gz'), 'archive_bytes': (DEST / 'results.tar.gz').stat().st_size,
              'file_count': len(files), 'uncompressed_bytes': size, 'manifest_sha256': sha(DEST / 'RESULTS_MANIFEST.json')}
    (DEST / 'ARCHIVE.json').write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps(result), flush=True)

if __name__ == '__main__':
    main()

